const searchDoc = $('Open Library Search').first().json.docs[0];
const workData = $json;
const isbn = $('ISBN Input').first().json.value1;

const coverId = searchDoc.cover_i;
const coverUrl = coverId ? `https://covers.openlibrary.org/b/id/${coverId}-M.jpg` : `https://covers.openlibrary.org/b/isbn/${isbn}-M.jpg`;

let description = 'Sin descripcion disponible.';
if (workData.description) {
  if (typeof workData.description === 'object') {
    description = workData.description.value || description;
  } else {
    description = workData.description;
  }
}

const author = searchDoc.author_name ? searchDoc.author_name[0] : 'Autor desconocido';
const year = searchDoc.first_publish_year || null;
const subjects = (workData.subjects || []).slice(0, 5).map(s => s.name || s);

function mapGenre(subjects) {
  const genreMap = {
    'fiction': 'Novela',
    'history': 'Historia',
    'poetry': 'Poesia',
    'drama': 'Teatro',
    'biography': 'Biografia',
    'fantasy': 'Fantasia',
    'horror': 'Terror',
    'mystery': 'Thriller',
    'science': 'Ensayo',
    'children': 'Infantil'
  };
  for (const subject of subjects) {
    const lower = subject.toLowerCase();
    for (const [key, value] of Object.entries(genreMap)) {
      if (lower.includes(key)) return value;
    }
  }
  return 'Otros';
}

const genre = mapGenre(subjects);

return {
  isbn: isbn,
  title: searchDoc.title || 'Titulo desconocido',
  author: author,
  year: year,
  genre: genre,
  coverUrl: coverUrl,
  description: description,
  subjects: subjects.join(', '),
  fechaEntrada: new Date().toISOString().split('T')[0]
};

const notionPage = $json;
return {
  success: true,
  message: `Libro creado: ${$('Normalizar Datos').first().json.title}`,
  isbn: $('Normalizar Datos').first().json.isbn,
  author: $('Normalizar Datos').first().json.author,
  notionUrl: notionPage.url || 'URL no disponible',
  genre: $('Normalizar Datos').first().json.genre,
  coverUrl: $('Normalizar Datos').first().json.coverUrl
};

const isbn = $('ISBN Input').first().json.value1;
return {
  success: false,
  message: `No se encontro el libro con ISBN: ${isbn} en Open Library`,
  isbn: isbn,
  suggestion: 'Prueba con Google Books API o introduce los datos manualmente'
};
